348		// A second version is charged in full; one that does not fit fails and
349		// leaves both the store and the counters untouched.
350		rec := putObject(t, h, "b1", "k", strings.Repeat("y", 500), nil)
351		wantError(t, rec, http.StatusConflict, "insufficient_capacity")
352		if p := getPoolView(t, h, "bp"); p["allocatedBytes"].(float64) != 600 {
353			t.Fatalf("allocated after failed version = %v", p)
354		}
355		if ov := decodeBody(t, do(h, http.MethodGet, "/v1/buckets/b1/object-versions", ""))["items"].([]any); len(ov) != 1 {
356			t.Fatalf("failed write left a version: %v", ov)
357		}
358		mustPutObject(t, h, "b1", "k", strings.Repeat("y", 400), nil)
359		if p := getPoolView(t, h, "bp"); p["allocatedBytes"].(float64) != 1000 {
360			t.Fatalf("allocated = %v", p)
361		}
362	}
363	
364	func TestEnableVersioningMigratesExistingObjects(t *testing.T) {
365		h := Handler()
366		createPool(t, h, bucketPool)
367		createBucket(t, h, `{"id":"b1","poolId":"bp"}`)
368		mustPutObject(t, h, "b1", "k", "abc", map[string]string{"X-Vaultgrid-Meta-A": "m"})
369		if p := getPoolView(t, h, "bp"); p["allocatedBytes"].(float64) != 3 {
370			t.Fatalf("allocated before enable = %v", p)
371		}
372		enableVersioning(t, h, "b1")
373		// Bytes are still charged once; the existing object is now a data version.
374		if p := getPoolView(t, h, "bp"); p["allocatedBytes"].(float64) != 3 {
375			t.Fatalf("allocated after enable = %v", p)
376		}
377		ov := decodeBody(t, do(h, http.MethodGet, "/v1/buckets/b1/object-versions", ""))["items"].([]any)
378		if len(ov) != 1 {
379			t.Fatalf("migrated rows = %v", ov)
380		}
381		row := ov[0].(map[string]any)
382		if row["versionId"].(string) == "" || row["isLatest"] != true || row["deleteMarker"] != false ||
383			row["sizeBytes"].(float64) != 3 || row["metadata"].(map[string]any)["A"] != "m" {
384			t.Fatalf("migrated row = %v", row)
385		}
386		id := row["versionId"].(string)
387		if rec := do(h, http.MethodGet, "/v1/buckets/b1/objects/k?versionId="+id, ""); rec.Code != http.StatusOK || rec.Body.String() != "abc" {
388			t.Fatalf("read migrated = %d %q", rec.Code, rec.Body.String())
389		}
390	}
