392	func TestVersionedAuditActions(t *testing.T) {
393		h := Handler()
394		createPool(t, h, bucketPool)
395		createBucket(t, h, `{"id":"b1","poolId":"bp"}`)
396		enableVersioning(t, h, "b1")
397		r1 := mustPutObject(t, h, "b1", "k", "abc", nil)
398		r2 := mustPutObject(t, h, "b1", "k", "defg", nil)
