400		id2 := decodeBody(t, r2)["versionId"].(string)
401		do(h, http.MethodDelete, "/v1/buckets/b1/objects/k", "")
402		ov := decodeBody(t, do(h, http.MethodGet, "/v1/buckets/b1/object-versions", ""))["items"].([]any)
403		markerID := ov[0].(map[string]any)["versionId"].(string)
404		do(h, http.MethodDelete, "/v1/buckets/b1/objects/k?versionId="+markerID, "")
405		do(h, http.MethodDelete, "/v1/buckets/b1/objects/k?versionId="+id1, "")
406		do(h, http.MethodDelete, "/v1/buckets/b1/objects/k?versionId="+id2, "")
407	
408		items := getAuditEvents(t, h, "/v1/audit-events?limit=1000")["items"].([]any)
409		var got []string
410		for _, raw := range items {
411			e := raw.(map[string]any)
412			if strings.HasPrefix(e["action"].(string), "object.") || e["action"] == "bucket.versioning-enabled" {
413				got = append(got, fmt.Sprintf("%s/%v", e["action"], e["bytesDelta"]))
414			}
415		}
416		want := []string{
417			"bucket.versioning-enabled/0",
418			"object.version-created/3",
419			"object.version-created/4",
420			"object.delete-marker-created/0",
421			"object.version-deleted/0", // marker
422			"object.version-deleted/-3",
423			"object.version-deleted/-4",
424		}
425		if len(got) != len(want) {
426			t.Fatalf("events = %v, want %v", got, want)
427		}
428		for i := range want {
429			if got[i] != want[i] {
430				t.Fatalf("event %d = %q, want %q (all: %v)", i, got[i], want[i], got)
431			}
