443		for i := 0; i < n; i++ {
444			wg.Add(1)
445			go func() {
446				defer wg.Done()
447				putObject(t, h, "b1", "k", "xxxx", nil)
448				do(h, http.MethodDelete, "/v1/buckets/b1/objects/other", "")
449			}()
