451		wg.Wait()
452	
453		// Whatever the serial order, counters must reconcile exactly with the
454		// surviving data versions and markers.
455		ov := decodeBody(t, do(h, http.MethodGet, "/v1/buckets/b1/object-versions", ""))["items"].([]any)
456		var dataBytes int64
457		for _, raw := range ov {
458			row := raw.(map[string]any)
459			if row["deleteMarker"] == false {
460				dataBytes += int64(row["sizeBytes"].(float64))
461			}
462		}
463		p := getPoolView(t, h, "cp")
464		if p["allocatedBytes"].(float64) != float64(dataBytes) {
465			t.Fatalf("allocated %v != version bytes %d (rows=%d)", p["allocatedBytes"], dataBytes, len(ov))
466		}
