286			t.Fatalf("pool after put = %v", p)
287		}
288		b := decodeBody(t, do(h, http.MethodGet, "/v1/buckets/b1", ""))
289		if b["objectCount"].(float64) != 1 || b["bytesUsed"].(float64) != 500 {
290			t.Fatalf("bucket counters = %v", b)
291		}
292	
293		// Overwrite adjusts only the delta.
294		mustPutObject(t, h, "b1", "k1", strings.Repeat("x", 550), nil)
295		if p := getPoolView(t, h, "bp"); p["allocatedBytes"].(float64) != 950 {
296			t.Fatalf("pool after grow = %v", p)
297		}
298		mustPutObject(t, h, "b1", "k1", strings.Repeat("x", 100), nil)
299		if p := getPoolView(t, h, "bp"); p["allocatedBytes"].(float64) != 500 {
300			t.Fatalf("pool after shrink = %v", p)
301		}
302	
303		// A write exceeding capacity fails and leaves the old object untouched.
304		rec := putObject(t, h, "b1", "k1", strings.Repeat("x", 700), map[string]string{"X-Vaultgrid-Meta-N": "1"})
305		wantError(t, rec, http.StatusConflict, "insufficient_capacity")
306		if p := getPoolView(t, h, "bp"); p["allocatedBytes"].(float64) != 500 {
307			t.Fatalf("pool after failed write = %v", p)
308		}
309		rec = do(h, http.MethodGet, "/v1/buckets/b1/objects/k1", "")
310		if rec.Body.String() != strings.Repeat("x", 100) || rec.Header().Get("X-Vaultgrid-Meta-N") != "" {
311			t.Fatalf("old object changed after failed write: %q meta=%q", rec.Body.String(), rec.Header().Get("X-Vaultgrid-Meta-N"))
312		}
313	
314		// A new object that does not fit is rejected too.
315		wantError(t, putObject(t, h, "b1", "k2", strings.Repeat("x", 501), nil), http.StatusConflict, "insufficient_capacity")
316	}
