318	func TestObjectConditionalWrites(t *testing.T) {
319		h := Handler()
320		createPool(t, h, bucketPool)
321		createBucket(t, h, `{"id":"b1","poolId":"bp"}`)
322		mustPutObject(t, h, "b1", "k", "v1", nil)
323		etag := sha256ETag("v1")
324	
325		// If-Match with the current etag succeeds.
326		rec := putObject(t, h, "b1", "k", "v2", map[string]string{"If-Match": etag})
327		if rec.Code != http.StatusOK {
328			t.Fatalf("if-match status = %d body = %s", rec.Code, rec.Body.String())
329		}
330		// If-Match with a stale etag fails with 412 and changes nothing.
331		stale := sha256ETag("other")
332		rec = putObject(t, h, "b1", "k", "v3", map[string]string{"If-Match": stale})
333		wantError(t, rec, http.StatusPreconditionFailed, "precondition_failed")
334		if rec := do(h, http.MethodGet, "/v1/buckets/b1/objects/k", ""); rec.Body.String() != "v2" {
335			t.Fatalf("object changed after 412: %q", rec.Body.String())
336		}
337		// If-Match against a missing object fails.
338		wantError(t, putObject(t, h, "b1", "missing", "x", map[string]string{"If-Match": etag}), http.StatusPreconditionFailed, "precondition_failed")
339	
340		// If-None-Match: * creates only when absent.
341		rec = putObject(t, h, "b1", "new", "x", map[string]string{"If-None-Match": "*"})
342		if rec.Code != http.StatusCreated {
343			t.Fatalf("if-none-match create status = %d body = %s", rec.Code, rec.Body.String())
344		}
345		wantError(t, putObject(t, h, "b1", "new", "y", map[string]string{"If-None-Match": "*"}), http.StatusPreconditionFailed, "precondition_failed")
346	
347		// Both headers together, or any other form, is a 400.
348		wantError(t, putObject(t, h, "b1", "k", "x", map[string]string{"If-Match": etag, "If-None-Match": "*"}), http.StatusBadRequest, "invalid_request")
349		wantError(t, putObject(t, h, "b1", "k", "x", map[string]string{"If-Match": "*"}), http.StatusBadRequest, "invalid_request")
350		wantError(t, putObject(t, h, "b1", "k", "x", map[string]string{"If-None-Match": etag}), http.StatusBadRequest, "invalid_request")
351		wantError(t, putObject(t, h, "b1", "k", "x", map[string]string{"If-Match": "unquoted"}), http.StatusBadRequest, "invalid_request")
