413	func TestConcurrentObjectWritesNeverOvercommit(t *testing.T) {
414		h := Handler()
415		createPool(t, h, bucketPool) // 1000 bytes
416		createBucket(t, h, `{"id":"b1","poolId":"bp"}`)
417	
418		const n = 20
419		var wg sync.WaitGroup
420		successes := make(chan int, n)
421		for i := 0; i < n; i++ {
422			wg.Add(1)
423			go func(i int) {
424				defer wg.Done()
425				rec := putObject(t, h, "b1", fmt.Sprintf("k%d", i), strings.Repeat("x", 100), nil)
